import os
import json
import re
import anthropic

def extract_structured_data(text_content: str) -> dict:
    """
    Extracts structured JSON data from a given text using the Anthropic Claude API.

    Args:
        text_content: The unstructured text to process.

    Returns:
        A dictionary containing the extracted structured data.
    """
    # It's a good practice to use an environment variable for the API key.
    # The Anthropic SDK automatically looks for ANTHROPIC_API_KEY.
    try:
        client = anthropic.Anthropic(api_key=os.environ.get("ANTHROPIC_API_KEY"))
    except Exception as e:
        print(f"Error initializing Anthropic client: {e}")
        print("Please ensure the ANTHROPIC_API_KEY environment variable is set.")
        return {}

    # The system prompt guides the model to behave in a specific way.
    system_prompt = (
        "You are a highly skilled data extraction AI. "
        "Your task is to identify and extract specific information from a given text "
        "and return it as a single, valid JSON object. Do not include any "
        "explanatory text, preambles, or markdown formatting like ```json ... ```. "
        "Just the raw JSON object."
    )

    # The user prompt contains the actual text and the extraction instructions.
    user_prompt = f"""
    Please extract the full name, email address, and the 10-digit invoice number from the following text.
    The invoice number is prefixed with 'INV-'.

    Text to analyze:
    'Dear Jane Doe, thank you for your recent purchase. We have attached the receipt for your records. You can reach our support at jane.doe@example.com. Your invoice number is INV-1234567890. Please let us know if you have any questions.'

    Desired JSON format:
    {{
      "fullName": "...",
      "email": "...",
      "invoiceNumber": "..."
    }}
    """

    try:
        message = client.messages.create(
            # Using a specific, cost-effective, and fast model from the Claude 3 family.
            model="claude-3-sonnet-20240229",
            max_tokens=1024,
            temperature=0.0,  # Lower temperature for more deterministic, factual output
            system=system_prompt,
            messages=[
                {
                    "role": "user",
                    "content": user_prompt
                }
            ]
        )

        raw_response = message.content[0].text

        # Models can sometimes wrap the JSON in markdown or add extra text.
        # This regex finds the JSON block.
        json_match = re.search(r'\{.*\}', raw_response, re.DOTALL)
        if json_match:
            json_string = json_match.group(0)
            return json.loads(json_string)
        else:
            # Fallback in case the regex fails, try parsing the whole string
            return json.loads(raw_response)

    except anthropic.APIError as e:
        print(f"An Anthropic API error occurred: {e}")
        return {}
    except json.JSONDecodeError:
        print(f"Failed to decode JSON from model response: {raw_response}")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}
